#include "daxa_refinement_common.hpp"
using namespace refinement_app;
int main(int argc,char** argv){try{
    if(argc==2&&std::string(argv[1])=="--shader-directory"){std::cout<<DaxaRefinement::shader_directory()<<'\n';return 0;}
    Options options(argc,argv);check(options.values.contains("--dump-prefix"),"diagnostic dump-prefix required");Prepared prepared(options);auto context=std::make_shared<DaxaFoundation>(options.validation);auto depth=std::make_unique<DaxaDepthPipeline>(prepared.coarse.rectification,prepared.depth,context,prepared.source);auto coarse=depth->enqueue(prepared.source);auto stage=std::make_unique<DaxaRefinement>(context,prepared.target.rectification,coarse,prepared.refinement);auto refined=stage->process(coarse);refined.wait();auto result=prepared.report();auto coarse_values=depth->readback(coarse);auto prefix=options.values.at("--dump-prefix");auto dump_coarse=[&](char const* name,auto const& values){auto path=prefix+".coarse_"+name;write(path,values.data(),values.size()*sizeof(typename std::remove_reference_t<decltype(values)>::value_type));result["coarse_files"][name]={{"path",path},{"sha256",daxa_preprocess_file_sha256(path)}};};dump_coarse("disparity.f32",coarse_values.lr_disparity);dump_coarse("confidence.f32",coarse_values.lr_confidence);dump_coarse("validity.u32",coarse_values.lr_validity);result["files"]=dump(stage->readback(refined),prefix);result["requested_refinement_buffer_bytes"]=stage->requested_buffer_bytes();result["actual_coarse_pipeline"]=true;result["diagnostic_injection"]=false;result["validation_requested"]=options.validation;result["device"]=json::parse(context->report());refined={};stage->collect();stage.reset();coarse={};depth->drain();depth.reset();context->close();check(!context->validation_errors&&!context->validation_warnings,"refinement fixture validation failed through teardown");result["validation_errors_after_teardown"]=context->validation_errors.load();result["validation_warnings_after_teardown"]=context->validation_warnings.load();prepared.verify(options);auto bytes=result.dump(2)+'\n';write(options.values.at("--output"),bytes.data(),bytes.size());return 0;
}catch(std::exception const& e){std::cerr<<"daxa_refinement_fixture: "<<e.what()<<'\n';return 1;}}
